INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (1, 'Milo', 'Perro', 'Golden Retriever', '2 años', 'Macho', '28 kg', 'Providencia, Santiago', 'https://images.unsplash.com/photo-1552053831-71594a27632d?auto=format&fit=crop&w=900&q=85', 'bg-[#e9d8c8]', 1, 1, '["Cariñoso","Juguetón","Amigable","Inteligente"]', 'Milo es un perro lleno de amor y energía. Le encanta jugar en el parque, dar paseos largos y sobre todo, recibir mimos. Es excelente con niños y se lleva de maravilla con otros perros.', '["Niños","Otros perros","Gatos"]', 'Alta', 2, 3, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (2, 'Luna', 'Gato', 'Criolla', '1 año', 'Hembra', '4 kg', 'Ñuñoa, Santiago', 'https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?auto=format&fit=crop&w=900&q=85', 'bg-[#d9e2d3]', 1, 1, '["Tranquila","Cariñosa","Independiente","Juguetona"]', 'Luna es una gata muy dulce y tranquila. Pasa la mayor parte del día dormitando en lugares soleados, pero cuando juega, ¡es una bola de energía!', '["Adultos","Otros gatos"]', 'Media', 1, 2, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (3, 'Bruno', 'Perro', 'Border Collie', '4 años', 'Macho', '19 kg', 'Las Condes, Santiago', 'https://images.unsplash.com/photo-1587300003388-59208cc962cb?auto=format&fit=crop&w=900&q=85', 'bg-[#eadfce]', 1, 1, '["Leal","Inteligente","Obediente","Energético"]', 'Bruno es un compañero fiel y muy inteligente. Sabe varias órdenes básicas y está ansioso por aprender más.', '["Niños mayores","Otros perros"]', 'Alta', 2, 3, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (4, 'Nala', 'Gato', 'Tabby', '3 meses', 'Hembra', '1.2 kg', 'La Florida, Santiago', 'https://images.unsplash.com/photo-1574158622682-e40e69881006?auto=format&fit=crop&w=900&q=85', 'bg-[#e5d8d1]', 0, 0, '["Curiosa","Traviesa","Mimosa","Aventurera"]', 'Nala es una pequeña exploradora que no tiene miedo a nada. Le encanta escalar muebles y perseguir bolitas por toda la casa.', '["Adultos","Gatos adultos pacientes"]', 'Alta', 1, 2, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (5, 'Bimbo', 'Perro', 'Criollo', '6 meses', 'Macho', '8 kg', 'Maipú, Santiago', 'https://images.unsplash.com/photo-1583511655857-d19b40a7a54e?auto=format&fit=crop&w=900&q=85', 'bg-[#ead9c6]', 1, 0, '["Juguetón","Cariñoso","Social","Inteligente"]', 'Bimbo es un cachorro lleno de vida y alegría. Fue rescatado de la calle con sus hermanitos y ahora busca un hogar para crecer rodeado de amor.', '["Niños","Otros perros","Gatos"]', 'Alta', 3, 4, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (6, 'Canela', 'Perro', 'Labrador', '3 años', 'Hembra', '25 kg', 'Puente Alto, Santiago', 'https://images.unsplash.com/photo-1583512603805-3cc6b41f3edb?auto=format&fit=crop&w=900&q=85', 'bg-[#e6eee1]', 1, 1, '["Dulce","Tranquila","Obediente","Leal"]', 'Canela es una perrita muy tranquila y amorosa. Le encanta acurrucarse en el sofá y dar paseos tranquilos por el parque. Es perfecta para una familia que busque compañía.', '["Niños","Adultos mayores","Otros perros"]', 'Media', 4, 5, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (7, 'Chiquita', 'Perro', 'Chihuahua', '5 años', 'Hembra', '2.3 kg', 'Viña del Mar', 'https://images.unsplash.com/photo-1558944351-6d4b0c9f0b57?auto=format&fit=crop&w=900&q=85', 'bg-[#e5d8d1]', 1, 1, '["Tímida","Cariñosa","Protectora","Dulce"]', 'Chiquita es una pequeña princesa que necesita tiempo para confiar, pero una vez que lo hace, es la compañera más leal del mundo. Prefiere hogares tranquilos sin niños pequeños.', '["Adultos","Ancianos"]', 'Baja', 1, 2, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (8, 'Firulais', 'Perro', 'Mestizo', '7 años', 'Macho', '14 kg', 'Ñuñoa, Santiago', 'https://images.unsplash.com/photo-1560807707-8cc77767d783?auto=format&fit=crop&w=900&q=85', 'bg-[#eadfce]', 1, 1, '["Leal","Tranquilo","Obediente","Cariñoso"]', 'Firulais es un perro senior muy tranquilo que ya pasó por mucho en la vida. Busca un hogar donde pueda pasar sus últimos años rodeado de mucho amor y descanso.', '["Adultos","Ancianos","Gatos tranquilos"]', 'Baja', 1, 2, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (9, 'Koda', 'Perro', 'Schnauzer', '2 años', 'Macho', '9 kg', 'Valparaíso', 'https://images.unsplash.com/photo-1519052537078-e6302a4968d4?auto=format&fit=crop&w=900&q=85', 'bg-[#d9e2d3]', 1, 1, '["Energético","Inteligente","Aventurero","Social"]', 'Koda es un perro lleno de energía y carácter. Le encanta salir a caminar, explorar nuevos lugares y jugar con otros perros. Sabe varias órdenes y está entrenado.', '["Niños mayores","Otros perros","Adultos"]', 'Alta', 2, 3, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (10, 'Lola', 'Perro', 'Beagle', '1 año', 'Hembra', '12 kg', 'Providencia, Santiago', 'https://images.unsplash.com/photo-1537151625747-768eb6cf92b2?auto=format&fit=crop&w=900&q=85', 'bg-[#e9d8c8]', 1, 1, '["Traviesa","Cariñosa","Social","Juguetona"]', 'Lola es una beagle curiosa y juguetona que le encanta seguir rastros y explorar. Es muy sociable y se lleva con todo el mundo. Perfecta para una familia activa.', '["Niños","Otros perros","Adultos"]', 'Alta', 3, 4, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (11, 'Morocho', 'Perro', 'Boxer', '4 años', 'Macho', '30 kg', 'Maipú, Santiago', 'https://images.unsplash.com/photo-1450778869180-41d0601e046e?auto=format&fit=crop&w=900&q=85', 'bg-[#ead9c6]', 1, 1, '["Protector","Leal","Juguetón","Mimoso"]', 'Morocho parece imponente por su tamaño, pero en realidad es un cachorro grande. Es muy protector de su familia y le encanta jugar todo el día.', '["Niños mayores","Adultos","Perros grandes"]', 'Media', 3, 4, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (12, 'Nina', 'Perro', 'Pug', '3 años', 'Hembra', '7 kg', 'La Florida, Santiago', 'https://images.unsplash.com/photo-1415369629372-26f2fe60c467?auto=format&fit=crop&w=900&q=85', 'bg-[#e6eee1]', 1, 1, '["Dulce","Tranquila","Mimosa","Cariñosa"]', 'Nina es una pugcita muy tierna que solo quiere dormir y recibir mimos. No necesita mucho ejercicio, ¡perfecta para departamento!', '["Ancianos","Adultos","Niños tranquilos"]', 'Baja', 4, 5, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (13, 'Pancho', 'Perro', 'Criollo', '8 años', 'Macho', '15 kg', 'Puente Alto, Santiago', 'https://images.unsplash.com/photo-1543466835-00a7907e9de1?auto=format&fit=crop&w=900&q=85', 'bg-[#eadfce]', 0, 1, '["Tranquilo","Leal","Independiente","Dulce"]', 'Pancho es un perro senior muy tranquilo que se rescató después de años viviendo en la calle. Ahora disfruta de una cama cómoda y comida todos los días.', '["Adultos","Ancianos","Gatos"]', 'Baja', 4, 5, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (14, 'Rocky', 'Perro', 'Mestizo', '10 meses', 'Macho', '11 kg', 'Viña del Mar', 'https://images.unsplash.com/photo-1477884213360-7e9d7dcc1e48?auto=format&fit=crop&w=900&q=85', 'bg-[#d9e2d3]', 1, 0, '["Energético","Juguetón","Social","Aventurero"]', 'Rocky es un cachorro muy activo que necesita una familia con tiempo para jugar y pasear. Está aprendiendo órdenes básicas y le va muy bien.', '["Niños","Otros perros"]', 'Alta', 3, 4, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (15, 'Solovino', 'Perro', 'Criollo', '12 años', 'Macho', '13 kg', 'Ñuñoa, Santiago', 'https://images.unsplash.com/photo-1543466835-00a7907e9de1?auto=format&fit=crop&w=900&q=85', 'bg-[#e5d8d1]', 1, 1, '["Tranquilo","Dulce","Cariñoso","Independiente"]', 'Solovino llegó al albergue después de que su dueño falleciera. Es un perro mayor muy noble que solo busca un lugar tranquilo para vivir sus últimos años.', '["Ancianos","Adultos"]', 'Baja', 1, 2, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (16, 'Toby', 'Perro', 'Beagle', '2 meses', 'Macho', '3.5 kg', 'Puente Alto, Santiago', 'https://images.unsplash.com/photo-1574144611937-0df059b5ef3e?auto=format&fit=crop&w=900&q=85', 'bg-[#ead9c6]', 0, 0, '["Juguetón","Curioso","Mimoso","Social"]', 'Toby es un cachorro de apenas 2 meses lleno de energía. Está en proceso de socialización y necesita una familia con paciencia para educarlo.', '["Niños","Otros perros","Adultos"]', 'Alta', 4, 5, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (17, 'Coco', 'Gato', 'Persa', '2 años', 'Hembra', '4.5 kg', 'Las Condes, Santiago', 'https://images.unsplash.com/photo-1596854407944-bf87f6fdd49e?auto=format&fit=crop&w=900&q=85', 'bg-[#e6eee1]', 1, 1, '["Independiente","Tranquila","Mimosa","Dulce"]', 'Coco es una gata persa muy elegante y tranquila. Le encanta que le cepillen su pelaje largo y dormir en lugares soleados de la casa.', '["Adultos","Ancianos","Gatos tranquilos"]', 'Baja', 5, 6, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (18, 'Garfield', 'Gato', 'Mestizo', '5 años', 'Macho', '6.8 kg', 'Las Condes, Santiago', 'https://images.unsplash.com/photo-1529778873920-4da4926a72c2?auto=format&fit=crop&w=900&q=85', 'bg-[#e9d8c8]', 1, 1, '["Dormilón","Independiente","Cariñoso","Travieso"]', 'Garfield vive a la altura de su nombre: le encanta dormir y comer. Es un gato gordito y muy cariñoso cuando quiere. Busca un hogar con mucho amor y comida.', '["Adultos","Ancianos"]', 'Baja', 5, 6, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (19, 'Kitty', 'Gato', 'Siames', '1 año', 'Hembra', '3.2 kg', 'Valparaíso', 'https://images.unsplash.com/photo-1533738363-b7f9aef128ce?auto=format&fit=crop&w=900&q=85', 'bg-[#eadfce]', 1, 1, '["Cariñosa","Vocal","Inteligente","Mimosa"]', 'Kitty es una siamesa muy conversadora y cariñosa. Siempre te estará saludando cuando llegues a casa y quiere estar cerca de ti en todo momento.', '["Adultos","Niños mayores","Otros gatos"]', 'Media', 5, 6, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (20, 'Mochi', 'Gato', 'Criolla', '8 meses', 'Macho', '2.8 kg', 'Las Condes, Santiago', 'https://images.unsplash.com/photo-1495360010541-f48722b34f7d?auto=format&fit=crop&w=900&q=85', 'bg-[#d9e2d3]', 1, 0, '["Juguetón","Curioso","Aventurero","Mimoso"]', 'Mochi es un gatito joven y juguetón que le encanta perseguir juguetes y saltar por todos lados. Es muy cariñoso y se duerme encima de ti por las noches.', '["Niños","Otros gatos","Perros tranquilos"]', 'Alta', 5, 6, '2026-09-07 18:54:16', 'en_adopcion');
INSERT INTO pets (id, name, type, breed, age, gender, weight, location, image, tone, vaccinated, sterilized, personality, about, good_with, energy, foundation_id, published_by, created_at, adoption_state) VALUES (21, 'Luna Junior', 'Perro', 'Criollito', '2 meses', NULL, '1.5 kg', 'Providencia, Santiago', 'https://images.unsplash.com/photo-1587300003388-59208cc962cb?w=800&auto=format&fit=crop', 'bg-[#ead9c6]', 0, 0, '["Tierno","Juguetón","Curioso"]', 'Luna Junior es una cachorrita muy cariñosa que ama jugar. Fue rescatada de la calle junto a su mamá y busca un hogar lleno de amor. Le encantan los mordederos y dormir al sol.', '["Niños","Otros perros"]', 'Alta', 1, 2, '2026-09-08 00:43:09', 'en_adopcion');
